<script>
 import { tick } from 'svelte';
 import { clockAppPages,clockAppSounds,clockAppZones,clockAppMeta,clockWorldPresentation,formatClockDuration } from './clock-app-state.js';
 import { clockAppMenus } from './clock-app-commands.js';
 import { createClockAppNativeView } from './clock-app-native-view.js';
 let {state: nativeClockState,profile,windowId,window,execute,registerView,available=()=>true,active=true,controls,sceneTime=0,systemClock,widgets}=$props();
 let root=$state(),feedback=$state('');
 const session=$derived(nativeClockState.windows.find(w=>w.windowId===windowId));
 const isWindows=$derived(profile.id.startsWith('windows'));
 const classic=$derived(/high-sierra|mojave/.test(profile.id));
 const meta=$derived(clockAppMeta(profile));
 const pageNames={world:'World Clock',alarms:'Alarms',stopwatch:'Stopwatch',timers:'Timers'};
 const world=$derived((widgets?.sources.clockCities??[]).map(row=>clockWorldPresentation(row,sceneTime,systemClock)));
 const notices=$derived(nativeClockState.alerts.filter(a=>['pending','delivered','snoozed'].includes(a.status)));
 const history=$derived([...nativeClockState.history].reverse());
 const fastest=$derived(nativeClockState.stopwatch.laps.length>1?Math.min(...nativeClockState.stopwatch.laps.map(l=>l.splitMs)):null);
 const slowest=$derived(nativeClockState.stopwatch.laps.length>1?Math.max(...nativeClockState.stopwatch.laps.map(l=>l.splitMs)):null);
 const stopwatchText=ms=>isWindows?formatClockDuration(ms,true):formatClockDuration(ms,true).replace(/^00:/,'');
 const alarmText=time=>{if(systemClock?.use24Hour)return time;const [h,m]=time.split(':');return `${Number(h)%12||12}:${m} ${Number(h)<12?'AM':'PM'}`;};
 const systemTime=$derived(new Intl.DateTimeFormat('en-US',{timeZone:systemClock?.timeZone??'UTC',hour:'numeric',minute:'2-digit',second:'2-digit',hour12:!systemClock?.use24Hour}).format(sceneTime));
 const cityChoices=[{name:'Los Angeles',timeZone:'America/Los_Angeles'},{name:'New York',timeZone:'America/New_York'},{name:'London',timeZone:'Europe/London'},{name:'Tokyo',timeZone:'Asia/Tokyo'},{name:'Coordinated Universal Time',timeZone:'UTC'}];
 const matches=$derived(cityChoices.filter(c=>`${c.name} ${c.timeZone}`.toLowerCase().includes(session?.query.toLowerCase()??'')));
 async function send(name,payload={},extra={}){try{const result=await execute(`clockApp.${name}`,{windowId,...extra},payload);feedback=result?.status==='rejected'?result.error?.message??'The Clock operation was not acknowledged.':'';return result;}catch(error){feedback=error.message;}}
 const draft=(field,value)=>send('draft',{field,value});
 const pref=(field,value)=>send('preferences',{...nativeClockState.preferences,[field]:value});
 function sheetKeys(event){if(event.key==='Escape'){event.preventDefault();void send('dialog',{kind:'none'});}if(event.key==='Tab'){const nodes=[...event.currentTarget.querySelectorAll('button,input,select')].filter(n=>!n.disabled),first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&event.target===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&event.target===last){event.preventDefault();first?.focus();}}}
 $effect(()=>{const actual=root,w=session;if(!actual||!w)return;const facade=createClockAppNativeView({getRoot:()=>root,getState:()=>nativeClockState,windowId,available:()=>typeof available==='function'?available():available===true,tick,getMenus:()=>clockAppMenus(nativeClockState,windowId,profile)});const unregister=registerView(windowId,facade);return()=>{facade.destroy();if(typeof unregister==='function')unregister();};});
</script>

{#snippet dial(hour,minute,second,size=130)}
 <svg class="clock-dial" viewBox="0 0 140 140" width={size} height={size} aria-hidden="true"><circle cx="70" cy="70" r="65" class="dial-face"/>{#each Array.from({length:12},(_,i)=>i) as n}<line x1="70" y1="10" x2="70" y2="16" transform={`rotate(${n*30} 70 70)`} class="dial-mark"/>{/each}<text x="70" y="33">12</text><text x="107" y="74">3</text><text x="70" y="117">6</text><text x="31" y="74">9</text><line x1="70" y1="76" x2="70" y2="38" transform={`rotate(${hour*30+minute/2} 70 70)`} class="hour-hand"/><line x1="70" y1="79" x2="70" y2="22" transform={`rotate(${minute*6+second/10} 70 70)`} class="minute-hand"/><line x1="70" y1="82" x2="70" y2="17" transform={`rotate(${second*6} 70 70)`} class="second-hand"/><circle cx="70" cy="70" r="3" fill="#ff9f0a"/></svg>
{/snippet}
{#if session}
<section bind:this={root} data-clock-app-window={windowId} class="native-clock" class:windows-clock={isWindows} class:classic-clock={classic} class:golden-clock={profile.id.includes('golden-gate')} aria-label={meta.localEquivalent?'Clock local equivalent':'Clock'}>
 <header class="clock-toolbar" inert={session.sheet!=='none'}>
  {#if isWindows}<strong class="app-heading">Clock</strong>{/if}
  <nav aria-label="Clock views">{#each clockAppPages as page}<button data-clock-control={`page:${page}`} class:selected={session.page===page} aria-pressed={session.page===page} onclick={()=>send('page',{page})}>{pageNames[page]}</button>{/each}</nav>
  <button class="add-button" data-clock-control="add" aria-label={session.page==='alarms'?'New alarm':session.page==='timers'?'New timer':'Add world clock city'} disabled={session.page==='stopwatch'} onclick={()=>send('dialog',{kind:session.page==='alarms'?'alarm':session.page==='timers'?'timer':'world'})}>＋</button>
  <button class="options-button" data-clock-control="options" aria-label="Clock options" onclick={()=>send('menu',{menu:session.menu?null:'Clock'})}>···</button>
 </header>
 {#if meta.localEquivalent||profile.id.includes('golden-gate')}<p class="era-disclosure">{meta.disclosure}</p>{/if}
 {#if profile.id==='macos-sonoma-14.0'&&session.page==='timers'}<p class="era-disclosure">Multiple timers are a disclosed local extension; Apple added multiple timers in macOS 14.2, after this base 14.0 profile.</p>{/if}
 {#if session.menu}<div class="clock-menu" role="menu" aria-label="Clock options">{#each clockAppMenus(nativeClockState,windowId,profile) as menu}<h3>{menu.label}</h3>{#each menu.items as item}<button role="menuitem" data-clock-control={`menu:${menu.id}:${item.id}`} disabled={!item.enabled} onclick={()=>item.request&&execute(item.request.command,item.request.target,item.request.payload)}>{item.checked?'✓ ':''}{item.label}</button>{/each}{/each}<button data-clock-control="close-menu" onclick={()=>send('menu',{menu:null})}>Close menu</button></div>{/if}
 <main data-clock-area="content" tabindex="0" inert={session.sheet!=='none'}>
  {#if isWindows}<h1 class="windows-page-heading">{pageNames[session.page]}</h1>{/if}
  {#if notices.length}<div class="clock-alerts" aria-label="Clock alerts">{#each notices as alert}<article class="clock-alert" role="status"><div><strong>{alert.label}</strong><small>{alert.kind==='timer'?'Timer ended':'Alarm'} · {alert.status==='pending'?'Awaiting shared notification acknowledgement':alert.status==='snoozed'?'Snoozed':`${alert.cycles>1?alert.cycles+' repeat cycles · ':''}Notification delivered`}</small></div>{#if alert.status!=='pending'}{#if alert.kind==='alarm'&&alert.status==='delivered'&&nativeClockState.alarms.find(a=>a.id===alert.sourceId)?.snooze}<button data-clock-control={`snooze:${alert.id}`} onclick={()=>send('alert',{action:'snooze'},{recordId:alert.id})}>Snooze {nativeClockState.preferences.snoozeMinutes} min</button>{/if}<button data-clock-control={`dismiss:${alert.id}`} onclick={()=>send('alert',{action:'dismiss'},{recordId:alert.id})}>Dismiss</button>{/if}</article>{/each}</div>{/if}
  {#if session.page==='world'}
   <div class="world-map" aria-label="Illustrative world map, selected clocks below"><svg viewBox="0 0 800 300" role="img" aria-label="World clock city markers on an illustrative local map"><defs><pattern id={`clock-grid-${windowId}`} width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="currentColor" stroke-opacity=".06"/></pattern></defs><rect width="800" height="300" fill={`url(#clock-grid-${windowId})`}/><g class="land"><path d="M54 61L94 44 136 48 175 32 229 42 260 66 235 88 220 89 199 119 174 132 160 164 143 157 137 124 104 105 80 103Z"/><path d="M186 149L223 163 249 190 239 225 217 272 201 267 202 229 181 203 174 175Z"/><path d="M365 61L398 41 441 45 466 27 522 46 588 37 651 54 694 81 677 106 632 114 609 101 571 120 555 160 534 160 512 130 491 106 462 113 449 94 424 111 389 101Z"/><path d="M385 111L424 104 457 126 469 157 449 179 431 224 407 217 394 183 371 148Z"/><path d="M627 211L666 186 709 194 731 215 709 240 662 246 635 235Z"/><path d="M431 224L440 214 443 240 435 254Z"/><path d="M654 117L658 97 665 104 663 124Z"/></g>{#each world as city}{@const pos=city.timeZone==='America/Los_Angeles'?[117,111]:city.timeZone==='America/New_York'?[210,102]:city.timeZone==='Europe/London'?[391,77]:city.timeZone==='Asia/Tokyo'?[662,114]:[400,142]}<circle cx={pos[0]} cy={pos[1]} r="4" class="city-dot"/><text x={pos[0]+8} y={pos[1]+4}>{city.name}</text>{/each}</svg></div>
   <div class="world-grid">{#each world as city,i}<article class="world-card">{@render dial(city.hour,city.minute,city.second)}<h2>{city.name}</h2><strong>{city.time}</strong><p>{city.date}</p><small>{city.timeZone}</small><label class="widget-city"><input type="checkbox" data-clock-control={`world-select:${city.id}`} checked={widgets.selected.clockCityIds.includes(city.id)} disabled={!widgets.selected.clockCityIds.includes(city.id)&&widgets.selected.clockCityIds.length>=4} onchange={event=>send('worldSelect',{cityIds:event.currentTarget.checked?[...widgets.selected.clockCityIds,city.id]:widgets.selected.clockCityIds.filter(id=>id!==city.id)})}/>Selected world city</label><div class="card-actions"><button data-clock-control={`world-up:${city.id}`} aria-label={`Move ${city.name} earlier`} disabled={i===0} onclick={()=>send('worldReorder',{index:i-1},{recordId:city.id})}>←</button><button data-clock-control={`world-down:${city.id}`} aria-label={`Move ${city.name} later`} disabled={i===world.length-1} onclick={()=>send('worldReorder',{index:i+1},{recordId:city.id})}>→</button><button data-clock-control={`world-delete:${city.id}`} onclick={()=>send('delete',{}, {recordId:city.id})}>Remove</button></div></article>{/each}</div>
   {#if !world.length}<div class="empty-clock"><h2>World Clock</h2><p>Add a city to see its time using real time-zone and daylight-saving rules.</p><button data-clock-control="world-add-empty" onclick={()=>send('dialog',{kind:'world'})}>Add City</button></div>{/if}
  {:else if session.page==='alarms'}
   <div class="alarm-grid">{#each nativeClockState.alarms as alarm}<article class:disabled-alarm={!alarm.enabled}><button class="alarm-time" data-clock-control={`alarm-edit:${alarm.id}`} onclick={()=>send('edit',{}, {recordId:alarm.id})}>{alarmText(alarm.time)}</button><label class="alarm-toggle"><input type="checkbox" data-clock-control={`alarm-enabled:${alarm.id}`} checked={alarm.enabled} onchange={event=>send('alarmSet',{enabled:event.currentTarget.checked},{recordId:alarm.id})}/><span>{alarm.enabled?'On':'Off'}</span></label><h2>{alarm.name}</h2><p>{alarm.days.length===7?'Every day':alarm.days.length?alarm.days.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', '):'Once'} · {alarm.timeZone}</p><small>{alarm.sound} (local label) · Snooze {alarm.snooze?'on':'off'}</small><button class="delete-alarm" data-clock-control={`alarm-delete:${alarm.id}`} onclick={()=>send('delete',{}, {recordId:alarm.id})}>Delete</button></article>{/each}</div>{#if !nativeClockState.alarms.length}<div class="empty-clock"><h2>No Alarms</h2><button data-clock-control="alarm-add-empty" onclick={()=>send('dialog',{kind:'alarm'})}>Add Alarm</button></div>{/if}
  {:else if session.page==='timers'}
   <div class="timer-grid">{#each nativeClockState.timers as timer}<article class="timer-card"><h2>{timer.name}</h2><div class="timer-dial"><svg viewBox="0 0 180 180" aria-hidden="true"><circle cx="90" cy="90" r="80" class="timer-track"/><circle cx="90" cy="90" r="80" class="timer-progress" stroke-dasharray="502.655" stroke-dashoffset={502.655*(1-(timer.durationMs?timer.remainingMs/timer.durationMs:0))}/></svg><strong>{formatClockDuration(timer.remainingMs,timer.remainingMs%1000!==0)}</strong></div><p>{timer.repeat?'Repeats':'One timer'} · {timer.completedCycles} completed</p><div class="timer-actions"><button class="quiet" data-clock-control={`timer-reset:${timer.id}`} onclick={()=>send('timer',{action:'reset'},{recordId:timer.id})}>Cancel / Reset</button><button class="start" data-clock-control={`timer-toggle:${timer.id}`} disabled={!timer.running&&timer.remainingMs===0&&timer.durationMs!==0} onclick={()=>send('timer',{action:timer.running?'pause':'start'},{recordId:timer.id})}>{timer.running?'Pause':'Start'}</button></div><div class="card-actions"><button data-clock-control={`timer-edit:${timer.id}`} disabled={timer.running} onclick={()=>send('edit',{}, {recordId:timer.id})}>Edit</button><button data-clock-control={`timer-delete:${timer.id}`} onclick={()=>send('delete',{}, {recordId:timer.id})}>Delete</button></div></article>{/each}</div>{#if !nativeClockState.timers.length}<div class="empty-clock"><h2>No Timers</h2><button data-clock-control="timer-add-empty" onclick={()=>send('dialog',{kind:'timer'})}>Add Timer</button></div>{/if}
  {:else}
   <div class="stopwatch-display">{#if nativeClockState.preferences.stopwatchStyle==='analog'}{@render dial(Math.floor(nativeClockState.stopwatch.elapsedMs/3600000),Math.floor(nativeClockState.stopwatch.elapsedMs/60000)%60,nativeClockState.stopwatch.elapsedMs/1000%60,220)}{/if}<strong>{stopwatchText(nativeClockState.stopwatch.elapsedMs)}</strong><div class="stopwatch-actions"><button class="quiet" data-clock-control="stopwatch-lap-reset" disabled={nativeClockState.stopwatch.running&&nativeClockState.stopwatch.laps.length>=512} onclick={()=>send('stopwatch',{action:nativeClockState.stopwatch.running?'lap':'reset'})}>{nativeClockState.stopwatch.running?'Lap':'Reset'}</button><button class="start" class:stop={nativeClockState.stopwatch.running} data-clock-control="stopwatch-toggle" onclick={()=>send('stopwatch',{action:nativeClockState.stopwatch.running?'pause':'start'})}>{nativeClockState.stopwatch.running?'Stop':'Start'}</button></div></div>
   <div class="lap-list" data-clock-area="laps" tabindex="0"><table><thead><tr><th>Lap</th><th>Split</th><th>Total</th></tr></thead><tbody>{#each nativeClockState.stopwatch.laps as lap,i}<tr class:fastest={lap.splitMs===fastest} class:slowest={lap.splitMs===slowest&&slowest!==fastest}><td>Lap {nativeClockState.stopwatch.laps.length-i}</td><td>{stopwatchText(lap.splitMs)}</td><td>{stopwatchText(lap.elapsedMs)}</td></tr>{/each}</tbody></table>{#if !nativeClockState.stopwatch.laps.length}<p class="lap-empty">Start the stopwatch, then record a lap.</p>{/if}</div>
  {/if}
  {#if session.page==='timers'||session.page==='stopwatch'}<details class="clock-history"><summary>Actual operation history ({nativeClockState.history.length})</summary><div data-clock-area="history" tabindex="0">{#each history as event}<p><time>{new Intl.DateTimeFormat('en-US',{timeZone:systemClock?.timeZone??'UTC',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:!systemClock?.use24Hour}).format(event.at)}</time> {event.action} · {event.sourceId} · {formatClockDuration(event.elapsedMs,true)}</p>{/each}</div><div class="card-actions"><button data-clock-control="clear-history" onclick={()=>send('clearHistory')}>Clear History</button><button data-clock-control="clear-completed" onclick={()=>send('clearCompleted')}>Clear Dismissed Alerts</button></div></details>{/if}
 </main>
 <footer><span>{systemTime} · {systemClock?.timeZone??'UTC'} · authored scene clock</span><span role="status">{feedback||'Runs while this window is closed. No host sounds or alarms.'}</span></footer>
 {#if session.sheet!=='none'}<div class="clock-scrim"><section class="clock-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='world'?'Add city':session.sheet==='alarm'?'Edit alarm':session.sheet==='timer'?'Edit timer':'Clock '+session.sheet} tabindex="-1" onkeydown={sheetKeys}>
  {#if session.draft}{@const d=session.draft}<h2>{d.id?'Edit':'Add'} {d.kind==='alarm'?'Alarm':'Timer'}</h2><label>Label<input data-clock-control="draft:name" value={d.name} maxlength="80" oninput={event=>draft('name',event.currentTarget.value)}/></label>
   {#if d.kind==='alarm'}<label>Time<input data-clock-control="draft:time" type="time" value={d.time} onchange={event=>draft('time',event.currentTarget.value)}/></label><label>Time Zone<select data-clock-control="draft:timeZone" value={d.timeZone} onchange={event=>draft('timeZone',event.currentTarget.value)}>{#each clockAppZones as zone}<option>{zone}</option>{/each}</select></label><fieldset><legend>Repeat (none means once)</legend>{#each ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as day,n}<label class="day-choice"><input data-clock-control={`draft:day:${n}`} type="checkbox" checked={d.days.includes(n)} onchange={event=>draft('days',event.currentTarget.checked?[...d.days,n].sort():d.days.filter(x=>x!==n))}/>{day}</label>{/each}</fieldset><label class="check-label"><input type="checkbox" data-clock-control="draft:snooze" checked={d.snooze} onchange={event=>draft('snooze',event.currentTarget.checked)}/>Snooze</label>
   {:else}<label>Duration (seconds)<input data-clock-control="draft:durationSeconds" type="number" min="0" max="359999" step="0.001" value={d.durationSeconds} oninput={event=>draft('durationSeconds',event.currentTarget.value)}/></label><label class="check-label"><input type="checkbox" data-clock-control="draft:repeat" checked={d.repeat} onchange={event=>draft('repeat',event.currentTarget.checked)}/>Repeat automatically</label><p class="sheet-note">Zero ends immediately; repeat requires a positive duration. Precise elapsed time follows only the authored scene clock.</p>{/if}
   <label>Sound label<select data-clock-control="draft:sound" value={d.sound} onchange={event=>draft('sound',event.currentTarget.value)}>{#each clockAppSounds as sound}<option>{sound}</option>{/each}</select></label><p class="sheet-note">Sound options are local alarm labels. No physical speaker or host notification permissions are used.</p><div class="sheet-actions"><button data-clock-control="cancel" onclick={()=>send('dialog',{kind:'none'})}>Cancel</button><button class="primary" data-clock-control="save" onclick={()=>send('save')}>Save</button></div>
  {:else if session.sheet==='world'}<h2>Add City</h2><label>Search cities<input data-clock-control="city-query" type="search" placeholder="City or time zone" value={session.query} oninput={event=>send('query',{query:event.currentTarget.value})}/></label><div class="city-results">{#each matches as city}<button data-clock-control={`city:${city.timeZone}`} onclick={()=>send('worldAdd',city)}><strong>{city.name}</strong><small>{city.timeZone}</small></button>{/each}{#if !matches.length}<p>No authored city matches. Try London, Tokyo or UTC.</p>{/if}</div><div class="sheet-actions"><button data-clock-control="cancel" onclick={()=>send('dialog',{kind:'none'})}>Cancel</button></div>
  {:else if session.sheet==='preferences'}<h2>Clock Settings</h2><label class="check-label"><input data-clock-control="pref:notifications" type="checkbox" checked={nativeClockState.preferences.notifications} onchange={event=>pref('notifications',event.currentTarget.checked)}/>Deliver to local Notification Center</label><label>Snooze minutes<input data-clock-control="pref:snooze" type="number" min="1" max="60" value={nativeClockState.preferences.snoozeMinutes} onchange={event=>pref('snoozeMinutes',Number(event.currentTarget.value))}/></label><label>Stopwatch<select data-clock-control="pref:stopwatchStyle" value={nativeClockState.preferences.stopwatchStyle} onchange={event=>pref('stopwatchStyle',event.currentTarget.value)}><option value="digital">Digital</option><option value="analog">Analog</option></select></label><p class="sheet-note">Clock display uses the same system Clock time zone and 12/24-hour preferences. Change those in system Date &amp; Time, not a duplicate setting here.</p><div class="sheet-actions"><button data-clock-control="done" onclick={()=>send('dialog',{kind:'none'})}>Done</button></div>
  {:else if session.sheet==='about'}<h2>Clock</h2><p>{meta.disclosure}</p><p>World clocks use Intl time-zone rules. Alarms, timers and stopwatch use one canonical authored scene clock. All scenes are local; no host settings or audio are changed.</p><div class="sheet-actions"><button data-clock-control="done" onclick={()=>send('dialog',{kind:'none'})}>Done</button></div>
  {:else}<h2>Clock Help</h2><p>Add world clocks with ＋. Alarm repeat days use each alarm’s time zone; nonexistent daylight-saving minutes are skipped and repeated minutes ring once.</p><p>Timers can repeat. Pause to edit. Reset a completed timer before starting again. Stopwatch laps preserve hundredths and actual split durations.</p><p>Alarms and timers keep running when windows close. Scene-time rewinds rebase counters without subtracting elapsed time or replaying completed alarms. Local Notification Center must acknowledge each real delivery.</p><div class="sheet-actions"><button data-clock-control="done" onclick={()=>send('dialog',{kind:'none'})}>Done</button></div>{/if}
  {#if feedback}<p class="sheet-error" role="alert">{feedback}</p>{/if}
 </section></div>{/if}
</section>
{/if}
<style>
 .native-clock{--clock-bg:#1c1c1e;--clock-card:#2c2c2e;--clock-text:#f4f4f5;--clock-muted:#aaa;--clock-line:#48484a;--clock-accent:#ff9f0a;position:relative;height:100%;display:flex;flex-direction:column;background:var(--clock-bg);color:var(--clock-text);font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',sans-serif;font-size:13px;overflow:hidden}.clock-toolbar{display:flex;align-items:center;gap:12px;padding:11px 16px;background:#242426;border-bottom:1px solid #080808}.clock-toolbar nav{display:flex;gap:2px;margin:auto;background:#3a3a3c;padding:2px;border-radius:7px}.native-clock button{font:inherit;color:inherit;border:0;border-radius:6px;background:#454547;padding:7px 12px;cursor:pointer}.native-clock button:hover{filter:brightness(1.18)}.native-clock button:disabled{opacity:.4;cursor:default}.native-clock button:focus-visible,.native-clock input:focus-visible,.native-clock select:focus-visible{outline:3px solid #007aff;outline-offset:2px}.clock-toolbar nav button{padding:5px 16px;background:transparent;color:#ddd}.clock-toolbar nav button.selected{background:#68686a;box-shadow:0 1px 3px #111;color:#fff}.clock-toolbar .add-button,.clock-toolbar .options-button{font-size:23px;background:transparent;padding:0 5px}.native-clock main{flex:1;min-height:0;overflow:auto;padding:20px}.era-disclosure{font-size:11px;margin:0;padding:6px 14px;background:#383426;color:#e9d4a5}.world-map{margin:0 -10px 20px;color:#ddd}.world-map svg{width:100%;height:auto;max-height:270px}.world-map .land{fill:#454548}.world-map text{fill:#ccc;font-size:11px}.city-dot{fill:var(--clock-accent)}.world-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:16px}.world-card{text-align:center;padding:6px}.world-card h2{font-size:16px;margin:12px 0 5px;font-weight:500}.world-card>strong{font-size:20px;font-weight:300;font-variant-numeric:tabular-nums}.world-card p{margin:5px;color:var(--clock-muted)}.world-card small{font-size:10px;color:var(--clock-muted)}.card-a